{"path": "/tmp/sv-c3b3dfb353d74a7c8a76565920cda14d/RecipeHub/Services/RecipeService.cs", "file_text": "using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt",
            Steps = "1. Preheat oven to 475°F.\n2. Roll out dough on floured surface.\n3. Spread crushed tomatoes evenly.\n4. Tear mozzarella and distribute.\n5. Bake 10-12 minutes until crust is golden.\n6. Top with fresh basil and drizzle olive oil."
        },
        new Recipe
        {
            Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
            Ingredients = "Spaghetti\nGuanciale (or pancetta)\nEgg yolks\nPecorino Romano\nBlack pepper",
            Steps = "1. Cook spaghetti in salted water.\n2. Crisp guanciale in a pan.\n3. Whisk egg yolks with grated pecorino.\n4. Toss hot pasta with guanciale.\n5. Remove from heat and stir in egg mixture.\n6. Season with black pepper and serve."
        },
        new Recipe
        {
            Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
            Ingredients = "Chicken breast\nYogurt\nGaram masala\nTurmeric\nCumin\nTomato sauce\nHeavy cream\nGarlic\nGinger",
            Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or broil chicken until charred.\n3. Sauté garlic and ginger in oil.\n4. Add tomato sauce and simmer.\n5. Stir in cream and spices.\n6. Add chicken pieces and simmer 10 minutes."
        },
        new Recipe
        {
            Id = 4, Title = "Vegetable Biryani", Category = "Indian",
            Ingredients = "Basmati rice\nMixed vegetables\nOnions\nYogurt\nBiryani masala\nSaffron\nMint\nCilantro\nGhee",
            Steps = "1. Soak rice for 30 minutes.\n2. Fry sliced onions until golden.\n3. Cook vegetables with spices.\n4. Layer rice and vegetable mixture.\n5. Add saffron milk and herbs.\n6. Cover and cook on low heat 20 minutes."
        },
        new Recipe
        {
            Id = 5, Title = "Beef Tacos", Category = "Mexican",
            Ingredients = "Ground beef\nTaco seasoning\nCorn tortillas\nLettuce\nTomato\nCheddar cheese\nSour cream\nSalsa",
            Steps = "1. Brown ground beef in a skillet.\n2. Add taco seasoning and water, simmer.\n3. Warm tortillas in a dry pan.\n4. Assemble tacos with beef and toppings.\n5. Serve with salsa and sour cream."
        },
        new Recipe
        {
            Id = 6, Title = "Guacamole", Category = "Mexican",
            Ingredients = "Avocados\nLime juice\nCilantro\nRed onion\nJalapeño\nTomato\nSalt\nGarlic",
            Steps = "1. Halve and pit avocados.\n2. Mash to desired consistency.\n3. Mix in diced onion, tomato, and jalapeño.\n4. Add lime juice, cilantro, and salt.\n5. Serve immediately with tortilla chips."
        },
        new Recipe
        {
            Id = 7, Title = "Miso Ramen", Category = "Japanese",
            Ingredients = "Ramen noodles\nMiso paste\nChicken broth\nSoy sauce\nSoft-boiled egg\nGreen onions\nNori\nChashu pork\nCorn",
            Steps = "1. Heat broth and whisk in miso paste.\n2. Season with soy sauce and mirin.\n3. Cook noodles according to package.\n4. Place noodles in bowls, ladle broth over.\n5. Top with sliced chashu, egg, corn, nori, and green onions."
        },
        new Recipe
        {
            Id = 8, Title = "Chocolate Chip Cookies", Category = "Desserts",
            Ingredients = "Butter\nSugar\nBrown sugar\nEggs\nVanilla extract\nFlour\nBaking soda\nSalt\nChocolate chips",
            Steps = "1. Cream butter and sugars until fluffy.\n2. Beat in eggs and vanilla.\n3. Mix flour, baking soda, and salt.\n4. Combine wet and dry ingredients.\n5. Fold in chocolate chips.\n6. Bake at 375°F for 9-11 minutes."
        },
        new Recipe
        {
            Id = 9, Title = "Tiramisu", Category = "Desserts",
            Ingredients = "Ladyfingers\nEspresso\nMascarpone\nEgg yolks\nSugar\nCocoa powder\nMarsala wine",
            Steps = "1. Brew espresso and let cool.\n2. Whisk yolks and sugar until thick.\n3. Fold in mascarpone.\n4. Dip ladyfingers briefly in espresso.\n5. Layer in dish: ladyfingers then cream.\n6. Repeat layers, dust with cocoa.\n7. Refrigerate at least 4 hours."
        }
    };

    private int _nextId = 10;

    public List<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public List<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars >= 1 && stars <= 5)
        {
            recipe.TotalRatingPoints += stars;
            recipe.RatingCount++;
        }
    }
}
"}

