@page "/category/{CategoryName}"
@inject RecipeHub.Services.RecipeService RecipeService

<PageTitle>@CategoryName Recipes - RecipeHub</PageTitle>

<h1>@CategoryName Recipes</h1>

@if (recipes.Any())
{
    <div class="row">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6 mb-3">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        @if (recipe.RatingCount > 0)
                        {
                            <p class="card-text text-warning">
                                @(new string('★', (int)Math.Round(recipe.AverageRating)))@(new string('☆', 5 - (int)Math.Round(recipe.AverageRating)))
                                <small class="text-muted">(@recipe.RatingCount ratings)</small>
                            </p>
                        }
                        <a href="recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}
else
{
    <p>No recipes found in this category.</p>
}

<a href="/" class="btn btn-secondary mt-3">← Back to Categories</a>

@code {
    [Parameter]
    public string CategoryName { get; set; } = string.Empty;

    private List<RecipeHub.Models.Recipe> recipes = new();

    protected override void OnParametersSet()
    {
        recipes = RecipeService.GetByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@inject RecipeHub.Services.RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe") - RecipeHub</PageTitle>

@if (recipe is null)
{
    <p>Recipe not found.</p>
}
else
{
    <h1>@recipe.Title</h1>
    <p><span class="badge bg-secondary">@recipe.Category</span></p>

    <h3>Ingredients</h3>
    <ul>
        @foreach (var ingredient in recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            <li>@ingredient</li>
        }
    </ul>

    <h3>Steps</h3>
    @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
    {
        <p>@step</p>
    }

    <h3>Rate this Recipe</h3>
    <StarRating RecipeId="recipe.Id" CurrentAverage="recipe.AverageRating" RatingCount="recipe.RatingCount" />

    <a href="category/@recipe.Category" class="btn btn-secondary mt-3">← Back to @recipe.Category</a>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private RecipeHub.Models.Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer
@inject RecipeHub.Services.RecipeService RecipeService

<div class="my-3">
    <div style="font-size: 1.5rem; cursor: pointer;">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span @onclick="() => Rate(star)" class="@(star <= hoverStar ? "text-warning" : "text-muted")"
                  @onmouseover="() => hoverStar = star"
                  @onmouseout="() => hoverStar = 0">
                ★
            </span>
        }
    </div>

    @if (submitted)
    {
        <div class="alert alert-success mt-2" role="alert">
            Thanks for rating! You gave @submittedStars star(s).
        </div>
    }

    @if (RatingCount > 0)
    {
        <small class="text-muted">Average: @CurrentAverage.ToString("F1") / 5 (@RatingCount ratings)</small>
    }
    else
    {
        <small class="text-muted">No ratings yet. Be the first!</small>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    [Parameter]
    public double CurrentAverage { get; set; }

    [Parameter]
    public int RatingCount { get; set; }

    private int hoverStar;
    private bool submitted;
    private int submittedStars;

    private void Rate(int stars)
    {
        RecipeService.AddRating(RecipeId, stars);
        var recipe = RecipeService.GetById(RecipeId);
        if (recipe is not null)
        {
            CurrentAverage = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
        submitted = true;
        submittedStars = stars;
    }
}

@page "/submit"
@rendermode InteractiveServer
@inject RecipeHub.Services.RecipeService RecipeService

<PageTitle>Submit a Recipe - RecipeHub</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (successMessage is not null)
{
    <div class="alert alert-success" role="alert">
        @successMessage
    </div>
}

<EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
    <DataAnnotationsValidator />
    <ValidationSummary />

    <div class="mb-3">
        <label for="title" class="form-label">Recipe Title</label>
        <InputText id="title" class="form-control" @bind-Value="model.Title" placeholder="e.g. Grandma's Apple Pie" />
    </div>

    <div class="mb-3">
        <label for="category" class="form-label">Category</label>
        <InputSelect id="category" class="form-select" @bind-Value="model.Category">
            <option value="">-- Select a category --</option>
            @foreach (var cat in RecipeService.GetCategories())
            {
                <option value="@cat">@cat</option>
            }
            <option value="Other">Other</option>
        </InputSelect>
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients (one per line)</label>
        <InputTextArea id="ingredients" class="form-control" rows="6" @bind-Value="model.Ingredients"
                       placeholder="2 cups flour&#10;1 cup sugar&#10;3 large apples..." />
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Steps (one per line)</label>
        <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="model.Steps"
                       placeholder="1. Preheat oven to 350°F.&#10;2. Mix dry ingredients..." />
    </div>

    <button type="submit" class="btn btn-success">Submit Recipe</button>
</EditForm>

@code {
    private RecipeFormModel model = new();
    private string? successMessage;

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(model.Title) ||
            string.IsNullOrWhiteSpace(model.Category) ||
            string.IsNullOrWhiteSpace(model.Ingredients) ||
            string.IsNullOrWhiteSpace(model.Steps))
        {
            return;
        }

        var recipe = new RecipeHub.Models.Recipe
        {
            Title = model.Title,
            Category = model.Category,
            Ingredients = model.Ingredients,
            Steps = model.Steps
        };

        RecipeService.AddRecipe(recipe);
        successMessage = $"'{model.Title}' submitted successfully!";
        model = new();
    }

    private class RecipeFormModel
    {
        public string Title { get; set; } = string.Empty;
        public string Category { get; set; } = string.Empty;
        public string Ingredients { get; set; } = string.Empty;
        public string Steps { get; set; } = string.Empty;
    }
}

